#pragma once
/**
 * @file RadarScope.h
 * @brief ImGui / ImPlot radar-echo scope (shared by GUI and VisualSystem).
 *
 * Displays the live radar echo / range-Doppler result generated by
 * RadarPulseProcessor:
 *   - range-doppler heatmap (ImPlot::PlotHeatmap)
 *   - range profile (peak over doppler per range bin)
 *   - doppler profile (peak over range per doppler bin)
 *   - timing statistics (sim time, frame, PRF, CPI pulse count, peak
 *     range / Doppler, platform-echo delay)
 *
 * Data is pushed from any thread via `setFrame()` (it only copies the
 * complex RD map into dB float buffers); `render()` issues ImGui calls
 * and must run inside a vsgImGui::RenderImGui callback (UI thread).
 */
#ifndef VSGRAYSIM_LAYER5_VIS_RADAR_SCOPE_H
#define VSGRAYSIM_LAYER5_VIS_RADAR_SCOPE_H

#include <cstdint>
#include <complex>
#include <vector>

#include "vsgraysim/layer3b_signal/SignalFrame.h"

namespace vsgraysim {

class RadarScope {
public:
    RadarScope();

    /// Replace the displayed RD map with the latest radar signal frame.
    void setFrame(const SignalFrame& frame);

    /// True when an RD map is available to draw.
    bool hasData() const { return w_ > 0 && h_ > 0; }

    bool visible() const { return visible_; }
    void setVisible(bool v) { visible_ = v; }

    /// Emit all ImGui / ImPlot draw calls for one frame.  Only call from
    /// within a vsgImGui::RenderImGui callback.  Returns the panel's open
    /// state (false when the user closed the window via its X button).
    bool render();

private:
    std::vector<float> rd_db_;             // row-major, row=doppler, col=range
    std::vector<float> range_profile_;     // max over doppler per range bin
    std::vector<float> doppler_profile_;   // max over range per doppler bin
    std::vector<float> range_axis_;        // per-bin range [m]
    std::vector<float> doppler_axis_;      // per-bin doppler [Hz]

    uint32_t w_ = 0;                       // range bins
    uint32_t h_ = 0;                       // doppler bins
    float    range_max_ = 0.0f;
    float    prf_ = 0.0f;
    double   carrier_hz_ = 0.0;
    uint32_t sensor_id_ = 0;
    double   sim_time_ = 0.0;
    uint64_t frame_id_ = 0;
    uint32_t coherent_pulses_ = 0;         // pulses accumulated in window

    // peak diagnostics
    uint32_t peak_row_ = 0;
    uint32_t peak_col_ = 0;
    float    peak_db_ = -120.0f;
    float    peak_range_m_ = 0.0f;
    float    peak_fd_hz_ = 0.0f;

    // ---- UI state (persisted across frames) ----
    bool visible_ = true;
    bool show_rd_ = true;
    bool show_range_profile_ = true;
    bool show_doppler_profile_ = false;
    bool auto_fit_ = true;
    float db_min_ = -60.0f;
    float db_max_ = 0.0f;
    int   colormap_ = 4; // ImPlotColormap_Viridis
};

} // namespace vsgraysim

#endif // VSGRAYSIM_LAYER5_VIS_RADAR_SCOPE_H